/// <summary>
/// Service class for Nat 3040 number update
/// </summary>
class METExciseNat3040RegisterUpdateService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// Process method to initiate business logic for Nat3040 number update
    /// </summary>
    public void process()
    {
        METExciseInformationNAT3040NumberMissing    metExciseInformationNAT3040NumberMissing;
        METExciseInformationTable       metExciseInformationTable;
        METNAT3040                      metNat3040;
        NumberSeq                       numberSeqNat30;
        NumberSeq                       numberSeqNat40;
        METNat30Number                  metNat30Number;
        METNat40Number                  metNat40Number;
        CustomerAttributeValueEntity    customerAttributeValueEntity;
        VendParameters                  vendParameters;
        SalesTable                      salesTable;
        
        void checkLodgement(METExciseInformationTable       _metExciseInformationTable) //Non blocking Warning log to let user know that transaction is missing. 
        {
            _metExciseInformationTable.reread();

            if (_metExciseInformationTable.Nat3040ReportNumber  && _metExciseInformationTable.Lodgement == '')
            {
                warning(strFmt("@MET:LodgementMissWarning", _metExciseInformationTable.Nat3040ReportNumber, _metExciseInformationTable.InventTransType, _metExciseInformationTable.ReferenceNumber));
            }
        }

        while select metExciseInformationNAT3040NumberMissing //View is already filtered with the parameter config and missing number
        {
            if (metExciseInformationNAT3040NumberMissing.InventTransType == InventTransType::Sales)
            {
                vendParameters = VendParameters::find();
                salesTable  = SalesTable::find(metExciseInformationNAT3040NumberMissing.ReferenceNumber);

                select firstonly RecId from customerAttributeValueEntity
                    where customerAttributeValueEntity.AccountNum == salesTable.CustAccount     &&
                     customerAttributeValueEntity.AttributeName == vendParameters.METExciseCustomerAttribute    &&
                    customerAttributeValueEntity.BooleanValue == NoYes::Yes;

                if (customerAttributeValueEntity.RecId)
                {
                    //Skipping the record for sales where customer attribute Duty free is set to yes
                    continue;
                }
            }

            try
            {
                ttsbegin;

                if (metExciseInformationNAT3040NumberMissing.ItemNAT3040 == METNAT3040::NAT30)
                {
                    if (metNat30Number == '')
                    {
                        numberSeqNat30 = NumberSeq::newGetNum(VendParameters::METnumRefNat30NumberSeq());
                        metNat30Number = numberSeqNat30.num();
                    }

                    metExciseInformationTable = metExciseInformationTable::findByRecId(metExciseInformationNAT3040NumberMissing.METExciseInformtionTableRecId, true);
                
                    if (metExciseInformationTable.RecId != 0)
                    {
                        metExciseInformationTable.NAT3040 = METNAT3040::NAT30;
                        metExciseInformationTable.Nat3040ReportNumber = metNat30Number;
                        metExciseInformationTable.update();

                        checkLodgement(metExciseInformationTable);
                    }
                    
                }
                else if (metExciseInformationNAT3040NumberMissing.ItemNAT3040 == METNAT3040::NAT40)
                {
                    if (metNat40Number == '')
                    {
                        numberSeqNat40 = NumberSeq::newGetNum(VendParameters::METnumRefNat40NumberSeq());
                        metNat40Number = numberSeqNat40.num();
                    }

                    metExciseInformationTable = metExciseInformationTable::findByRecId(metExciseInformationNAT3040NumberMissing.METExciseInformtionTableRecId, true);
                
                    if (metExciseInformationTable.RecId != 0)
                    {
                        metExciseInformationTable.NAT3040 = METNAT3040::NAT40;
                        metExciseInformationTable.Nat3040ReportNumber = metNat40Number;
                        metExciseInformationTable.update();

                        checkLodgement(metExciseInformationTable);
                    }
                }

                ttscommit;
            }
            catch
            {
                exceptionTextFallThrough();
            }
        }
    }
